mapper.sql:
ass.id, ass.sn, ass.model_id, ass.host, ass.state, ass.purchase_date, ass.create_at, ass.update_at,
/*数据中心*/ idc.id AS idc_id, idc.name AS idc_name, idc.location AS idc_location, idc.tel AS idc_tel, idc.principal AS idc_principal,
/*机柜*/ cab.id AS cab_id, cab.name AS cab_name, cab.idc_id AS cab_idcId, cab.u_size AS cab_uSize, cab.remark AS cab_remark,
/*用户*/ su.user_id AS su_user_id, su.username AS su_username, su.password AS su_password, su.salt AS su_salt, su.email AS su_email, su.status AS su_status, su.create_time AS su_createTime,
su1.user_id AS su1_user_id, su1.username AS su1_username, su1.password AS su1_password, su1.salt AS su1_salt, su1.email AS su1_email, su1.status AS su1_status, su1.create_time AS su1_createTime,
/*module统计 关联endPoint表*/ (SELECT COUNT(ep.id) FROM endpoint ep WHERE ep.asset_id = ass.id) AS moduleNum, /*alert统计 关联alert_rule表*/ (SELECT COUNT(ar.id) FROM alert_rule ar WHERE ass.id = ar.link_id AND ar.type = 3) AS alertNum

mapper.select:
SELECT

FROM asset ass

LEFT JOIN idc idc ON ass.idc_id = idc.id
LEFT JOIN cabinet cab ON ass.cabinet_id = cab.id
LEFT JOIN sys_user su ON ass.create_by = su.user_id
LEFT JOIN sys_user su1 ON ass.update_by = su1.user_id

WHERE 1=1


    AND ass.id = #{params.id}



    AND ass.model_id = #{params.modelId}



    AND ass.idc_id = #{params.idcId}



    AND ass.idc_id IN

        #{idcId}




    AND ass.cabinet_id = #{params.cabinetId}



    AND ass.state = #{params.state}



    AND ass.host like CONCAT('%', #{params.host}, '%')



    AND ass.sn like CONCAT('%', #{params.sn}, '%')



    AND ass.purchase_date like CONCAT('%', #{params.purchaseDate}, '%')

SELECT id, sn, host, state FROM asset
host in
#{item}
